"use strict";(self.webpackChunkdocs=self.webpackChunkdocs||[]).push([[7092],{86697:e=>{e.exports=JSON.parse('{"functions":[],"properties":[],"types":[],"name":"Rng","desc":"Tiny deterministic PRNG (32-bit xorshift) with a Roblox `Random`-compatible\\nsurface (`NextNumber`, `NextInteger`), so it drops into anything that takes a\\n`Random` (e.g. PoissonDisk). Use it when the SAME seed must yield the SAME\\nstream every run \u2014 per-chunk procedural placement that has to look identical\\nacross server restarts and across clients.\\n\\n```lua\\nlocal rng = Rng.new(seed)\\nrng:NextNumber()      -- [0, 1)\\nrng:NextInteger(1, 6) -- inclusive both ends\\n```","source":{"line":19,"path":"src/Shared/Modules/Rng.luau"}}')}}]);